-- 5. SEED DỮ LIỆU TẤT CẢ 9 BÀI BÁO & BẢNG TIN
INSERT INTO public.articles (id, title, excerpt, content, date_display, read_time, category, image, author, is_hero, display_order)
VALUES
(
  'news-1-chinsu-pho-story',
  '{"vi":"Bắt tay cùng Phở Thìn Bờ Hồ, Chin-su ra mắt phở ăn liền \"Phở Story\" mang hương vị phở gia truyền đến mọi miền","en":"Partnering with Pho Thin Bo Ho, Chin-su Launches \"Pho Story\" Instant Pho Bringing Ancestral Heritage Everywhere","zh":"携手还剑湖薄瘦牛肉粉：Chin-su推出“Pho Story”速食牛肉粉，传世美味香飘四海","ko":"퍼틴 보 호와 손잡고 출시한 친수(Chin-su) \"Pho Story\" 인스턴트 쌀국수: 전통의 맛을 온 세상으로"}'::jsonb,
  '{"vi":"Chin-su chính thức hợp tác cùng Phở Thìn Bờ Hồ ra mắt sản phẩm phở ăn liền \"Phở Story\", đánh dấu một bước tiến đưa giá trị ẩm thực truyền thống Việt Nam đến gần hơn với đời sống hiện đại.","en":"Chin-su officially partners with Pho Thin Bo Ho to launch \"Pho Story\" instant pho, marking a milestone in bringing traditional Vietnamese cuisine closer to modern life.","zh":"Chin-su正式携手还剑湖薄瘦牛肉粉推出“Pho Story”速食产品，标志着将越南传统饮食精粹融入现代生活的里程碑。","ko":"친수가 퍼틴 보 호와 공식 협력하여 \"Pho Story\" 쌀국수를 출시, 전통 미식의 가치를 현대인의 일상에 더 가깝게 전합니다."}'::jsonb,
  '{"vi":["Chin-su chính thức hợp tác cùng Phở Thìn Bờ Hồ ra mắt sản phẩm phở ăn liền \"Phở Story\", đánh dấu một bước tiến trong hành trình đưa những giá trị của ẩm thực truyền thống Việt Nam đến gần hơn với đời sống hiện đại.","Phở Thìn Bờ Hồ có lịch sử từ năm 1955 và được biết đến là một trong những hàng phở lâu đời tại Hà Nội. Trải qua hơn 70 năm, thương hiệu vẫn duy trì hương vị phở thanh tao, cùng không gian mang nét cổ kính tại số 61 Đinh Tiên Hoàng, quận Hoàn Kiếm, Hà Nội. Năm 2019, Phở Thìn Bờ Hồ cũng được lựa chọn phục vụ tại Hội nghị Thượng đỉnh Mỹ - Triều, góp phần đưa món phở truyền thống Hà Nội đến với đông đảo khách quốc tế.","Với mong muốn tái hiện hương vị phở gia truyền trong một sản phẩm tiện lợi, Chin-su đã phối hợp cùng nghệ nhân Phở Thìn Bờ Hồ để phát triển công thức nước dùng. Sản phẩm ứng dụng công nghệ hiện đại, thực hiện quy trình hầm xương và trích ly trong nhiều giờ nhằm tạo ra phần nước dùng cô đặc, giữ lại những nét đặc trưng của phở truyền thống.","Đại diện Chin-su cho biết, \"Phở Story\" được xây dựng như một chuỗi câu chuyện về phở Việt Nam, bắt đầu với câu chuyện của Phở Thìn Bờ Hồ và hướng tới việc tiếp nối bằng những câu chuyện về các món phở đặc trưng khác trên khắp Việt Nam. Qua đó, thương hiệu mong muốn kết hợp giữa giá trị truyền thống và sự nhanh chóng, tiện lợi của sản phẩm hiện đại.","Về phía Phở Thìn Bờ Hồ, đây là lần đầu tiên thương hiệu hợp tác kinh doanh để đưa hương vị phở truyền thống đến người tiêu dùng thông qua sản phẩm đóng gói. Sự hợp tác này mở ra một cách tiếp cận mới để thực khách có thể thưởng thức hương vị Phở Thìn Bờ Hồ thuận tiện hơn, đồng thời góp phần lan tỏa câu chuyện về ẩm thực Việt Nam.","Phở Story vì vậy không chỉ là một sản phẩm phở ăn liền mà còn là sự kết hợp giữa hương vị gia truyền, công nghệ hiện đại và câu chuyện văn hóa ẩm thực Việt, tiếp nối hành trình đưa những món ngon truyền thống đến gần hơn với người tiêu dùng."],"en":["Chin-su officially collaborates with Pho Thin Bo Ho to launch the \"Pho Story\" instant pho line, advancing traditional Vietnamese gastronomy into contemporary everyday life.","Originating in 1955, Pho Thin Bo Ho is one of Hanoi’s most venerable pho establishments. Over 70 years, the brand preserves its delicate broth elegance at 61 Dinh Tien Hoang, Hoan Kiem. In 2019, Pho Thin Bo Ho was chosen to cater the historic US-DPRK Summit.","Aiming to recreate heritage flavors in a convenient format, Chin-su and Pho Thin artisans developed an authentic concentrated bone-broth formula through multi-hour extraction.","For Pho Thin Bo Ho, this premier commercial alliance introduces ancestral recipes into packaged goods, allowing patrons worldwide to enjoy genuine Hanoi flavors effortlessly."],"zh":["Chin-su正式携手还剑湖薄瘦牛肉粉推出“Pho Story”速食牛肉粉，迈出将越南传统饮食文化融入现代快捷生活的坚实一步。","还剑湖薄瘦牛肉粉自1955年创牌，为河内最享盛誉的古法名店之一。70年来始终坚守清冽醇厚的汤头精髓。2019年更荣选为美朝领导人峰会招待美食。","双方历经数月研发，运用高科技多重萃取工艺，完美浓缩了丁先皇街61号慢炖高汤的醇美骨髓鲜甜。"],"ko":["친수(Chin-su)가 하노이의 전설적인 퍼틴 보 호와 손잡고 \"Pho Story\" 쌀국수를 공식 출시했습니다.","1955년부터 딘 띠엔 황 61번지에서 70년 넘게 맑고 담백한 육수를 지켜온 퍼틴 보 호는 2019년 북미 정상회담 만찬 메뉴로도 선정된 바 있습니다.","첨단 사골 농축 공법을 통해 70년 가문의 전통 육수 비법을 언제 어디서나 간편하게 맛볼 수 있도록 재현했습니다."]}'::jsonb,
  '04/10/2023',
  '5 phút đọc',
  '{"vi":"Hợp Tác & Phát Triển","en":"Strategic Partnership","zh":"战略合作","ko":"전략적 제휴"}'::jsonb,
  '/src/assets/images/regenerated_image_1790961081614.jpg',
  'Admin',
  TRUE,
  1
),
(
  'news-2-ngay-viet-nam-nuoc-ngoai',
  '{"vi":"Ngày Việt Nam ở nước ngoài 2023: Mang Phở Thìn, tranh Đông Hồ đến quốc tế","en":"Vietnam Day Abroad 2023: Bringing Pho Thin and Dong Ho Folk Paintings to the World","zh":"2023年海外越南日：携薄瘦牛肉粉与东湖木刻版画闪耀世界舞台","ko":"2023 해외 베트남의 날: 퍼틴 쌀국수와 동호 판화를 세계에 알리다"}'::jsonb,
  '{"vi":"Hình ảnh bát Phở Thìn Bờ Hồ thơm nức cùng những bức tranh dân gian Đông Hồ đã trở thành đại sứ văn hoá chạm đến trái tim bạn bè quốc tế.","en":"Steaming bowls of Pho Thin Bo Ho alongside vibrant Dong Ho woodblock prints became cultural ambassadors touching hearts worldwide.","zh":"还剑湖畔热气腾腾的牛肉粉携手古朴典雅的东湖版画，化作传递越南文化温情的亮丽使者。","ko":"김이 모락모락 나는 퍼틴 보 호 쌀국수와 동호 민속 판화가 세계인의 마음을 사로잡은 문화 대사로 활약했습니다."}'::jsonb,
  '{"vi":["Trong khuôn khổ chương trình \"Ngày Việt Nam ở nước ngoài 2023\", Phở Thìn Bờ Hồ vinh dự đại diện cho ẩm thực truyền thống Thủ Đô giới thiệu nét tinh hoa văn hoá ẩm thực Việt Nam đến bạn bè năm châu.","Tại không gian văn hoá, thực khách quốc tế không chỉ được chiêm ngưỡng những bức tranh Đông Hồ mộc mạc mà còn được trực tiếp thưởng thức từng thìa nước dùng thanh tao trong veo đặc trưng của người Tràng An.","Nhiều chính khách, nghệ sĩ và du khách quốc tế đã bày tỏ sự thán phục trước chiều sâu văn hoá và sự tinh tế trong cách nấu phở truyền thống hơn 70 năm của gia tộc cụ Thìn."],"en":["During the \"Vietnam Day Abroad 2023\" program, Pho Thin Bo Ho proudly represented Hanoi’s traditional gastronomy, introducing Vietnam’s culinary pinnacle to global delegates.","International guests marvelled at pastoral Dong Ho paintings while tasting the delicate, crystal-clear broth distinctive of ancient Trang An elegance.","Diplomats and cultural connoisseurs expressed deep admiration for the 70-year family devotion behind every ladle of soup."],"zh":["在“2023海外越南日”系列盛会中，还剑湖薄瘦牛肉粉作为首都传统饮食瑰宝代表，向五洲四海宾客展示了越南饮食文化的深厚底蕴。","外国友人在欣赏质朴典雅的东湖民间版画之余，亦亲口领略了传承七十载的透亮清甜原汤魅力。"],"ko":["2023 해외 베트남의 날 행사에서 퍼틴 보 호는 수도 하노이의 대표 전통 미식으로서 베트남 음식 문화의 정수를 선보였습니다.","세계 각국의 외교관과 관광객들은 소박한 동호 판화를 감상하며 맑고 깊은 70년 전통 육수를 맛보고 찬사를 아끼지 않았습니다."]}'::jsonb,
  '09/11/2023',
  '4 phút đọc',
