  'Admin',
  FALSE,
  5
),
(
  'news-6-pho-yeu-thuong',
  '{"vi":"Phở Thìn Bờ Hồ đồng hành cùng chương trình \"Phở Yêu Thương\"","en":"Pho Thin Bo Ho Joins Hands with the \"Pho of Love\" Community Program","zh":"还剑湖薄瘦牛肉粉温情同行“爱心米粉”公益项目","ko":"퍼틴 보 호, 따뜻한 나눔을 실천하는 \"사랑의 쌀국수\" 프로젝트 동행"}'::jsonb,
  '{"vi":"Hàng nghìn bát phở nóng hổi chan chứa tình nghĩa đã được trao tận tay các hoàn cảnh khó khăn, lan toả tinh thần nhân ái của người Tràng An.","en":"Thousands of piping hot, heartfelt bowls of pho delivered to underprivileged communities, sharing Trang An generosity.","zh":"数千碗温热喷香的传统高汤牛肉粉送到困难群体手中，传递河内人的博爱温情。","ko":"어려운 이웃들에게 전해진 수천 그릇의 따뜻한 쌀국수, 하노이 사람들의 따뜻한 정을 나눕니다."}'::jsonb,
  '{"vi":["Với tâm niệm ẩm thực không chỉ là kinh doanh mà còn là sự sẻ chia và phụng sự cộng đồng, Phở Thìn Bờ Hồ thường xuyên tổ chức các hoạt động thiện nguyện thiết thực.","Trong chương trình \"Phở Yêu Thương\", gia đình nghệ nhân Phở Thìn đã tự tay chuẩn bị từng nồi nước dùng ngọt thanh, chuẩn bị những phần phở nóng sốt trao tận tay các bệnh nhân nghèo và người có hoàn cảnh khó khăn.","Mỗi bát phở trao đi không chỉ mang giá trị dinh dưỡng ấm lòng mà còn sưởi ấm niềm tin, lan tỏa thông điệp yêu thương và gắn kết cộng đồng giữa lòng Thủ Đô."],"en":["Believing cuisine is about heartfelt sharing and community service, Pho Thin Bo Ho regularly conducts impactful charity initiatives.","Through \"Pho of Love\", Thin family artisans personally simmered fresh broth pots, serving nourishing hot pho to impoverished patients and vulnerable families.","Each bowl carries more than nourishment; it sparks hope, spreading warmth and unity across Hanoi."],"zh":["秉承美食源于关怀与奉献的初心，薄瘦牛肉粉持续积极开展各项暖心公益善举。","在“爱心米粉”活动中，手艺人亲自起火熬汤，将一碗碗营养滚烫的爱心牛肉粉送抵困难群众手中。"],"ko":["음식은 단순한 사업이 아닌 나눔이라는 신념으로, 퍼틴 보 호는 정기적인 사회 공헌 활동을 이어오고 있습니다.","가문 장인들이 직접 끓여낸 정성 가득한 쌀국수를 이웃들에게 대접하며 따뜻한 희망의 온기를 나눕니다."]}'::jsonb,
  '13/08/2024',
